CREATE TABLE portfolio_policies(policy_id uuid PRIMARY KEY,version text NOT NULL,min_cash numeric NOT NULL,max_instrument numeric NOT NULL,market_caps jsonb NOT NULL,industry_caps jsonb NOT NULL,max_turnover numeric NOT NULL,account_max_age_seconds integer NOT NULL,tolerance numeric NOT NULL);
CREATE TABLE portfolio_sleeve_policies(sleeve_id uuid PRIMARY KEY,policy_id uuid NOT NULL REFERENCES portfolio_policies,kind text NOT NULL,budget numeric NOT NULL CHECK(budget BETWEEN 0 AND 1),required boolean NOT NULL,priority integer NOT NULL CHECK(priority>0),UNIQUE(policy_id,kind));
CREATE TABLE target_portfolios(target_id uuid PRIMARY KEY,policy_id uuid NOT NULL REFERENCES portfolio_policies,strategy_run_ids jsonb NOT NULL,account_snapshot_id uuid NOT NULL,built_at timestamptz NOT NULL,cash_weight numeric NOT NULL CHECK(cash_weight BETWEEN 0 AND 1),input_hash char(64) UNIQUE NOT NULL,content_hash char(64) NOT NULL);
CREATE TABLE target_weights(weight_id uuid PRIMARY KEY,target_id uuid NOT NULL REFERENCES target_portfolios,instrument_id uuid NOT NULL REFERENCES instruments,weight numeric NOT NULL CHECK(weight BETWEEN 0 AND 1),UNIQUE(target_id,instrument_id));
CREATE TABLE target_contributions(contribution_id uuid PRIMARY KEY,target_id uuid NOT NULL REFERENCES target_portfolios,sleeve text NOT NULL,instrument_id uuid,raw_weight numeric NOT NULL,final_weight numeric NOT NULL,cash_contribution numeric NOT NULL);
CREATE TABLE constraint_results(result_id uuid PRIMARY KEY,target_id uuid NOT NULL REFERENCES target_portfolios,rule text NOT NULL,scope text NOT NULL,before numeric NOT NULL,after numeric NOT NULL,limit_value numeric NOT NULL,binding boolean NOT NULL,reason text NOT NULL,severity text NOT NULL);
CREATE TABLE rebalance_deltas(delta_id uuid PRIMARY KEY,target_id uuid NOT NULL REFERENCES target_portfolios,instrument_id uuid NOT NULL REFERENCES instruments,current_weight numeric NOT NULL,target_weight numeric NOT NULL,delta numeric NOT NULL,UNIQUE(target_id,instrument_id));
CREATE TABLE portfolio_events(event_id uuid PRIMARY KEY,event_type text NOT NULL,target_id uuid NOT NULL,occurred_at timestamptz NOT NULL,reasons jsonb NOT NULL,input_hash text);
